const formattedDate=()=>new Date().toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
const pageRoute=()=>{const r=location.hash.replace('#','').split('/')[0];return headings[r]?r:'overview'};
let route=pageRoute(), level={listening:'easy',reading:'easy',writing:'easy'}, section={listening:0,reading:0,writing:1}, talkSet='A',talkPhase='p1',talkIndex=0,showTranscript=false,showReview=false,recorder=null,recordedBlob=null,recordingStream=null,voiceQueue=false,ttsToken=0;
let timer={seconds:0,running:false,interval:null,kind:''};
const levels={listening:['easy','moderate','extreme'],reading:['easy','moderate','high'],writing:['easy','moderate','high']};
const testKey=(skill,lvl)=>`${skill}:${lvl}`;
const answers=(skill,lvl)=>S.answers[testKey(skill,lvl)]||{};
const getResult=(skill,lvl)=>S.results[testKey(skill,lvl)]||null;
const countWords=text=>(String(text).trim().match(/\b[\p{L}\p{N}]+(?:['’-][\p{L}\p{N}]+)*\b/gu)||[]).length;
const pretty=k=>({easy:'Easy',moderate:'Moderate',high:'High',extreme:'Extreme'})[k]||k;
const nameBand=b=>b===null||b===undefined?'—':Number(b).toFixed(1);
const scoreAvg=vals=>M.mean(vals.filter(x=>typeof x==='number'&&Number.isFinite(x)));
function toast(message){let el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast._t);toast._t=setTimeout(()=>el.classList.remove('show'),2800)}
function nav(){const items=['overview','listening','reading','writing','speaking','tracker','schedule'];$('#nav').innerHTML=items.map(id=>`<a href="#${id}" class="nav-link ${route===id?'active':''}" data-nav="${id}">${ico(id)}<span>${headings[id]}</span></a>`).join('');$('#crumb').innerHTML=`Workspace <span>/ ${headings[route]}</span>`}
function heading(ey,title,desc,buttons=''){return `<div class="page-head"><div><div class="eyebrow">${ey}</div><h1>${title}</h1><p>${desc}</p></div>${buttons}</div>`}
const badge=(label,type='teal')=>`<span class="badge ${type}">${esc(label)}</span>`;
function resultMark(skill,lvl){const r=getResult(skill,lvl);return r?badge(`Band ${nameBand(r.band)}`,'teal'):badge('Not completed')}
function picker(skill,levelsArr){return `<div class="segmented" role="tablist" aria-label="Difficulty">${levelsArr.map(l=>`<button role="tab" aria-selected="${level[skill]===l}" class="${level[skill]===l?'active':''}" data-action="level" data-skill="${skill}" data-level="${l}">${pretty(l)} ${getResult(skill,l)?'✓':''}</button>`).join('')}</div>`}
function timerBar(seconds,kind){if(timer.kind!==kind){stopTimer();timer.kind=kind;timer.seconds=seconds}return `<div class="timer-chip">${ico('clock',15)} <span id="clock-display">${clockText(timer.seconds)}</span></div>`}
function clockText(s){s=Math.max(0,s|0);return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function startTimer(){if(timer.running)return;timer.running=true;timer.interval=setInterval(()=>{timer.seconds--;if(timer.seconds<=0){timer.seconds=0;stopTimer();toast('Time is up. Complete or review your attempt.')}const disp=$('#clock-display');if(disp)disp.textContent=clockText(timer.seconds)},1000);toast('Timer started')}
function stopTimer(){timer.running=false;if(timer.interval){clearInterval(timer.interval);timer.interval=null}}
function timerControls(){return `<div class="row wrap"><button class="btn btn-secondary btn-sm" data-action="timer-${timer.running?'pause':'start'}">${ico(timer.running?'pause':'play',13)} ${timer.running?'Pause':'Start'} timer</button><button class="btn btn-ghost btn-sm" data-action="timer-reset">${ico('refresh',13)} Reset</button></div>`}
function heroStats(){const vals=Object.values(S.results), best=scoreAvg(vals.map(r=>r.band));const completed=vals.length;const skillCount=new Set(vals.map(x=>x.skill)).size;return {completed,skillCount,best:best===null?'—':nameBand(best)}}
function renderOverview(){const st=heroStats();return `${heading('STUDY DASHBOARD','Your IELTS practice, in one place.','Prepare all four IELTS skills with original mock tests, structured feedback and progress tracking.')}<section class="hero"><div><div class="eyebrow">YOUR NEXT STEP STARTS HERE</div><h2>Build confidence.<br>One mock test at a time.</h2><p>Choose a skill, complete a timed mock, understand your errors and monitor progress towards your target band.</p><button class="btn" data-action="go" data-route="listening">Start a mock test ${ico('arrow',16)}</button></div><div class="hero-aside"><div class="hero-ring"><b>${esc(String(S.target))}</b><span>TARGET BAND</span></div></div></section>
<div class="section-head"><h2>At a glance</h2>${badge('Progress saved locally')}</div><div class="grid-4">${[['Tests completed',st.completed,'file'],['Skills practised',`${st.skillCount}/4`,'check'],['Practice band average',st.best,'tracker'],['Target band',nameBand(S.target),'flag']].map(x=>`<div class="card stat-card"><div class="stat-top"><span class="stat-icon">${ico(x[2])}</span>${badge('PROGRESS','blue')}</div><div class="value">${esc(x[1])}</div><div class="stat-label">${esc(x[0])}</div></div>`).join('')}</div>
<div class="section-head"><h2>Choose your practice</h2><span class="muted">Full question sets & guided review</span></div><div class="grid-4">${[['listening','Listening','Easy, Moderate and Extreme; 40 questions per set.'],['reading','Academic Reading','Three original sets with 40 questions each.'],['writing','Academic Writing','Three levels, Task 1 charts and Task 2 essays.'],['speaking','Speaking','Three realistic examiner-led interviews with recording.']].map(x=>`<div class="card skill-card"><span class="skill-icon">${ico(x[0])}</span><div><h3>${x[1]}</h3><p class="desc">${x[2]}</p></div><div class="foot"><span data-action="go" data-route="${x[0]}" role="button" tabindex="0">Open ${x[1]}</span>${ico('arrow',15)}</div></div>`).join('')}</div>
<div class="section-head"><h2>Your recent activity</h2><button class="btn btn-secondary btn-sm" data-action="go" data-route="tracker">View score tracker ${ico('arrow',14)}</button></div><div class="grid-main"><div class="card">${renderRecent(5)}</div><div class="card"><h3>Study-day plan</h3><p style="margin-bottom:17px">A focused 10:00 AM – 8:00 PM practice schedule across three rounds.</p><div class="row-between" style="margin:12px 0"><span class="badge teal">Round 1</span><strong>Easy</strong><span class="muted">10:00–12:35</span></div><div class="row-between" style="margin:12px 0"><span class="badge blue">Round 2</span><strong>Moderate</strong><span class="muted">1:20–4:05</span></div><div class="row-between" style="margin:12px 0"><span class="badge gold">Round 3</span><strong>High / Extreme</strong><span class="muted">4:20–7:15</span></div><hr class="separator"><button class="btn btn-secondary" data-action="go" data-route="schedule">View full schedule ${ico('arrow')}</button></div></div><p class="footer-note">Scores from question-based tests are estimates of IELTS band equivalents. Speaking and Writing require human judgement; self-assessed scores are not official IELTS results.</p>`}
function renderRecent(n){let list=[...S.history].reverse().slice(0,n);if(!list.length)return `<div class="empty-state"><h3>No completed tests yet</h3><p>Start a Listening or Reading test to see your first scored result here.</p></div>`;return `<div class="table-wrap"><table class="scores-table"><thead><tr><th>Skill</th><th>Difficulty</th><th>Band</th><th>Date</th></tr></thead><tbody>${list.map(x=>`<tr><td><strong>${esc(headings[x.skill]||x.skill)}</strong></td><td>${esc(pretty(x.level))}</td><td>${badge(`Band ${nameBand(x.band)}`)}</td><td>${esc(new Date(x.at).toLocaleDateString('en-GB'))}</td></tr>`).join('')}</tbody></table></div>`}
function listeningSections(lvl){const l=D.listening[lvl];if(lvl!=='extreme')return l.map((p,i)=>({title:p.title,subtitle:p.subtitle,people:p.people,lines:p.lines,instructions:p.instructions,questions:p.questions.map(q=>({...q,type:'short'}))}));return l.sections.map((s,i)=>({title:s.title,subtitle:s.context,people:s.speakers,lines:s.lines,instructions:l.questions[i][1],questions:l.questions[i][2].map(([n,prompt])=>({n,prompt,answer:l.answers[String(n)],why:l.explanations[String(n)]||'Refer to the recording.',type:'short'}))}))}
function listeningQuestions(lvl){return listeningSections(lvl).flatMap(p=>p.questions)}
function renderPartNav(parts,current){return `<div class="part-tabs">${parts.map((p,i)=>`<button class="part-tab ${i===current?'active':''}" data-action="part" data-part="${i}">Part ${i+1}<span class="little">${p.questions.length} Qs</span></button>`).join('')}</div>`}
function renderQuestion(q,skill,lvl,review){const key=testKey(skill,lvl),ans=answers(skill,lvl),val=ans[String(q.n)]||'',isCorrect=review&&M.correct(val,q.answer,q.accept||[]);const input=q.type==='tfn'?`<select class="select" data-answer="${key}" data-number="${q.n}"><option value="">Choose an answer</option>${q.options.map(x=>`<option value="${esc(x)}" ${val===x?'selected':''}>${esc(x)}</option>`).join('')}</select>`:q.type==='choice'?`<select class="select" data-answer="${key}" data-number="${q.n}"><option value="">Choose an option</option>${q.options.map((x,i)=>`<option value="${'ABCD'[i]}" ${val==='ABCD'[i]?'selected':''}>${'ABCD'[i]}. ${esc(x)}</option>`).join('')}</select>`:`<input class="input" type="text" autocomplete="off" spellcheck="false" data-answer="${key}" data-number="${q.n}" aria-label="Answer question ${q.n}" placeholder="Your answer" value="${esc(val)}">`;
return `<div class="question ${review?(isCorrect?'review-good':'review-bad'):''}"><div class="row-between"><span class="qnum">${q.n}</span>${review?badge(isCorrect?'Correct':'Review',isCorrect?'teal':'red'):''}</div><div class="qprompt">${esc(q.prompt)}</div>${input}${review?`<div class="review-line ${isCorrect?'':'bad'}">Answer: <b>${esc(q.answer)}</b> · ${esc(q.why||'')}</div>`:''}</div>`}
function renderListening(){const lev=level.listening,parts=listeningSections(lev),p=parts[section.listening]||parts[0],all=listeningQuestions(lev),responses=answers('listening',lev),answered=all.filter(q=>String(responses[q.n]||'').trim()).length;const result=getResult('listening',lev);const review=showReview&&!!result;
return `${heading('SKILL 01 · LISTENING','Listen with focus. Answer with precision.','40 questions across four sections. Use normal speed first, then replay and read transcripts during review.',resultMark('listening',lev))}<div class="test-toolbar">${picker('listening',levels.listening)}<div class="row wrap">${timerBar(35*60,`listening:${lev}`)}${timerControls()}</div></div><div class="row-between" style="margin-bottom:14px"><span class="muted"><b id="answered-count">${answered}</b>/40 answers completed</span><div class="row wrap">${result?`<button class="btn btn-secondary btn-sm" data-action="toggle-review">${showReview?'Hide':'Show'} answer review</button>`:''}<button class="btn btn-ghost btn-sm" data-action="retake">${ico('refresh',13)} Retake</button></div></div><div class="progress-track" style="margin-bottom:19px"><div id="answer-progress" class="progress-fill" style="width:${answered/40*100}%"></div></div>${renderPartNav(parts,section.listening)}<div class="practice-layout"><div class="card"><div class="row-between"><div><span class="eyebrow">LISTENING SECTION ${section.listening+1}</span><h3 style="margin-top:5px">${esc(p.title)}</h3></div>${badge('10 questions','blue')}</div><p>${esc(p.subtitle||'')}</p>${renderAudio(lev,p,section.listening)}${lev==='extreme'&&section.listening===1?museumMap():''}<div class="callout warn">${esc(p.instructions)}</div><hr class="separator"><div class="row-between"><button class="btn btn-secondary btn-sm" data-action="toggle-transcript">${showTranscript?'Hide transcript':'Reveal transcript'}</button><span class="fine">Avoid transcripts during the first attempt.</span></div>${showTranscript?`<div style="margin-top:15px">${p.lines.map(([code,line])=>`<div class="speaker-turn"><b>${esc(p.people[code]||code)}</b><p>${esc(line)}</p></div>`).join('')}</div>`:''}</div><div class="card"><div class="row-between"><h3>Questions ${p.questions[0].n}–${p.questions[p.questions.length-1].n}</h3>${result?badge(`Last: ${nameBand(result.band)}`):''}</div><p>Answers are saved automatically as you type.</p>${p.questions.map(q=>renderQuestion(q,'listening',lev,review)).join('')}<div class="row-between wrap" style="margin-top:19px"><button class="btn btn-secondary" data-action="part" data-part="${Math.max(0,section.listening-1)}" ${section.listening===0?'disabled':''}>Previous part</button>${section.listening<3?`<button class="btn btn-primary" data-action="part" data-part="${section.listening+1}">Next part ${ico('chevron')}</button>`:`<button class="btn btn-primary" data-action="submit-skill" data-skill="listening">Mark all 40 answers ${ico('check')}</button>`}</div>${result?scoreSummary(result):''}</div></div>`}
function museumMap(){return `<div class="chart-box" style="margin:16px 0"><div class="small-title">Ground-floor plan · entrance on the south side</div><svg viewBox="0 0 470 330" style="width:100%;max-height:310px" role="img" aria-label="Museum floor plan. North on top. Upper rooms A B C, lower rooms D E F; entrance directly below E."><text x="235" y="22" text-anchor="middle" font-size="14" fill="#3f6c69">NORTH ↑</text><rect x="30" y="38" width="410" height="235" rx="9" fill="#eef6f3" stroke="#4d827b" stroke-width="2"/><path d="M166 38V273 M303 38V273 M30 155H440" stroke="#aec8c4" stroke-width="3"/><rect x="182" y="263" width="107" height="24" fill="#fff"/><text x="235" y="318" text-anchor="middle" font-size="14" font-weight="800" fill="#245d57">↑ ENTRANCE</text>${['A','B','C','D','E','F'].map((a,i)=>{const col=i%3,row=i<3?0:1;return `<circle cx="${98+col*137}" cy="${93+row*120}" r="24" fill="${a==='E'?'#c7994d':'#117c70'}"/><text x="${98+col*137}" y="${100+row*120}" text-anchor="middle" font-size="21" font-weight="800" fill="white">${a}</text>`}).join('')}</svg><div class="fine">Letters indicate locations, not room names. E is the reception area.</div></div>`}
function renderAudio(lvl,p,part){if(lvl==='extreme')return `<div class="audio-panel"><div class="audio-title">OFFLINE AUDIO · SECTION ${part+1}</div><audio controls preload="none" id="extreme-audio" src="assets/audio/extreme-part-${part+1}.mp3">Audio unavailable in this browser.</audio><p>This section uses the clearer synthetic MP3 from the earlier Extreme test. Keep all audio files alongside the app.</p></div>`;return `<div class="audio-panel"><div class="audio-title">BROWSER VOICE PLAYBACK · SECTION ${part+1}</div><div class="row wrap" style="margin:14px 0"><button class="btn btn-primary btn-sm" data-action="speech-start">${ico('play',14)} Play section</button><button class="btn btn-secondary btn-sm" data-action="speech-stop">${ico('stop',14)} Stop</button></div><div class="row wrap"><select class="select" id="voice-select" aria-label="Choose narrator voice" style="flex:1;min-width:140px"><option value="">Best English voice (automatic)</option></select><select class="select" id="speed-select" aria-label="Playback speed" style="width:105px"><option value="1">1.0× speed</option><option value="0.88">0.88× speed</option><option value="0.78">0.78× speed</option><option value="1.08">1.08× speed</option></select></div><div class="speech-status" id="speech-status" style="margin-top:9px">Natural-sounding voices depend on your browser and operating system.</div></div>`}
function scoreSummary(r){return `<div class="score-result" style="margin-top:20px"><div><div class="small-title">Latest practice result</div><div class="fine">${esc(r.raw!==undefined?r.raw+'/40 correct · ':'' )}${esc(r.note||'Approximate band equivalent')}</div></div><strong>${nameBand(r.band)}</strong></div>`}
function readingParts(lev){let n=0;return D.reading[lev].passages.map(p=>({...p,questions:p.questions.map(q=>({...q,n:++n}))}))}
function renderReading(){const lev=level.reading,parts=readingParts(lev),p=parts[section.reading]||parts[0],all=parts.flatMap(x=>x.questions),val=answers('reading',lev),count=all.filter(q=>String(val[q.n]||'').trim()).length,r=getResult('reading',lev),review=showReview&&!!r;
return `${heading('SKILL 02 · ACADEMIC READING','Read deeply. Think critically.','Three original Academic Reading practice sets with 40 questions each. Passages are condensed for targeted practice.',resultMark('reading',lev))}<div class="test-toolbar">${picker('reading',levels.reading)}<div class="row wrap">${timerBar(60*60,`reading:${lev}`)}${timerControls()}</div></div><div class="row-between" style="margin-bottom:14px"><span class="muted"><b id="answered-count">${count}</b>/40 answers completed</span><div class="row wrap">${r?`<button class="btn btn-secondary btn-sm" data-action="toggle-review">${showReview?'Hide':'Show'} answer review</button>`:''}<button class="btn btn-ghost btn-sm" data-action="retake">${ico('refresh',13)} Retake</button></div></div><div class="progress-track" style="margin-bottom:19px"><div class="progress-fill" id="answer-progress" style="width:${count/40*100}%"></div></div>${renderPartNav(parts,section.reading)}<div class="practice-layout reading"><div class="card sticky-pane"><span class="eyebrow">READING PASSAGE ${section.reading+1}</span><h3 style="font-size:19px;margin:7px 0 19px">${esc(p.title)}</h3><div class="passage-text">${p.paras.map(pa=>`<p>${esc(pa)}</p>`).join('')}</div></div><div class="card"><div class="row-between"><h3>Questions ${p.questions[0].n}–${p.questions[p.questions.length-1].n}</h3>${badge(`${p.questions.length} questions`,'blue')}</div><p>For TRUE/FALSE/NOT GIVEN, choose only what the passage establishes. Complete other answers with a short word or phrase.</p>${p.questions.map(q=>renderQuestion(q,'reading',lev,review)).join('')}<div class="row-between wrap" style="margin-top:17px"><button class="btn btn-secondary" data-action="part" data-part="${Math.max(0,section.reading-1)}" ${section.reading===0?'disabled':''}>Previous passage</button>${section.reading<2?`<button class="btn btn-primary" data-action="part" data-part="${section.reading+1}">Next passage ${ico('chevron')}</button>`:`<button class="btn btn-primary" data-action="submit-skill" data-skill="reading">Mark all 40 answers ${ico('check')}</button>`}</div>${r?scoreSummary(r):''}</div></div><div class="callout" style="margin-top:19px">This is independent, original practice material—not an official IELTS paper. Each set has 40 questions, but the reading passages are shorter than the approximately 2,150–2,750 total words in the official Academic Reading test.</div>`}
const writingCriteria1=['Task Achievement','Coherence & Cohesion','Lexical Resource','Grammar & Accuracy'],writingCriteria2=['Task Response','Coherence & Cohesion','Lexical Resource','Grammar & Accuracy'],speakingCriteria=['Fluency & Coherence','Lexical Resource','Grammar & Accuracy','Pronunciation'];
